// HTTP handler for the WhatsApp-style web chat (web/index.html). Judges open it from a QR code,
// so there is no join step. It reuses the same inbound processor as the Twilio webhook:
// same engine, same database, same privacy rules.
import { z } from "zod";
import type { ParsedInbound } from "../messaging/types.ts";

const MAX_IMAGE_DATA_URL = 8_000_000; // about 6 MB of image; the page downsizes photos first

const bodySchema = z.object({
  /** Random id generated by the browser, kept in localStorage. Hashed before storage. */
  clientId: z.uuid(),
  /** Random id per message, so a retried request is not processed twice. */
  messageId: z.uuid(),
  text: z.string().max(2000).optional().default(""),
  image: z
    .object({ dataUrl: z.string().max(MAX_IMAGE_DATA_URL).regex(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/) })
    .optional(),
  location: z.object({ lat: z.number().min(-90).max(90), lng: z.number().min(-180).max(180) }).optional(),
});

export type WebChatRequest = z.input<typeof bodySchema>;

export interface WebChatDeps {
  processInbound: (parsed: ParsedInbound) => Promise<string[]>;
  /** CORS origin allowed to call this endpoint. The page is static and public, so "*" is fine. */
  allowOrigin?: string;
}

export function createWebChatHandler(deps: WebChatDeps): (req: Request) => Promise<Response> {
  const cors = {
    "Access-Control-Allow-Origin": deps.allowOrigin ?? "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "content-type, authorization, apikey, x-client-info",
  };
  const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });

  return async (req) => {
    if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

    let raw: unknown;
    try {
      raw = await req.json();
    } catch {
      return json({ error: "Invalid JSON" }, 400);
    }
    const parsed = bodySchema.safeParse(raw);
    if (!parsed.success) return json({ error: "Invalid message" }, 400);
    const body = parsed.data;

    const media = body.image
      ? [{ url: body.image.dataUrl, contentType: body.image.dataUrl.slice(5, body.image.dataUrl.indexOf(";")) }]
      : [];

    const replies = await deps.processInbound({
      messageSid: `WEB${body.messageId.replace(/-/g, "")}`,
      from: body.clientId,
      channel: "web",
      text: body.text.trim(),
      media,
      location: body.location ?? null,
    });
    return json({ replies });
  };
}
